        value = self._parse_multiplicative()
        while self._current[0] == _OP and self._current[1] in ("+", "-"):
            op = self._advance()[1]
            right = self._parse_multiplicative()
            value = self._apply_binary(op, value, right)
        return value

    # Next precedence: * / // %.
    def _parse_multiplicative(self):
        value = self._parse_unary()
        while self._current[0] == _OP and self._current[1] in (
            "*", "/", "//", "%"
        ):
            op = self._advance()[1]
            right = self._parse_unary()
            value = self._apply_binary(op, value, right)
        return value

    # Unary operators bind less tightly than **.
    def _parse_unary(self):
        if self._current[0] == _OP and self._current[1] in ("+", "-"):
            op = self._advance()[1]
            operand = self._parse_unary()
            return self._apply_unary(op, operand)
        return self._parse_power()

    # ** is right-associative and its right operand may have unary operators.
    def _parse_power(self):
        value = self._parse_primary()
        if self._current[0] == _OP and self._current[1] == "**":
            self._advance()
            exponent = self._parse_unary()
            return self._apply_binary("**", value, exponent)
        return value

    def _parse_primary(self):
        token = self._current

        if token[0] == _NUMBER:
            self._advance()
            text = token[1]
            if "." in text:
                try:
                    return float(text)
                except ValueError:
                    raise CalcError("invalid number: {!r}".format(text))
            try:
                return int(text)
            except ValueError:
                raise CalcError("invalid number: {!r}".format(text))

        if token[0] == _IDENT:
            self._advance()
            name = token[1]
            if self._current[0] == _LPAREN:
                return self._parse_call(name)
            if name in self._env:
                return self._env[name]
            raise CalcError("unknown variable: {!r}".format(name))

        if token[0] == _LPAREN:
            self._advance()
            value = self._parse_additive()
            if self._current[0] != _RPAREN:
                if self._current[0] == _EOF:
                    raise self._unbalanced("unbalanced parentheses: missing ')'")
                raise self._unexpected()
            self._advance()
            return value

        raise self._unexpected(token)

    def _parse_call(self, name):
        # The identifier has already been consumed; consume the opening paren.
        self._advance()
        args = []

        if self._current[0] != _RPAREN:
            args.append(self._parse_additive())
            while self._current[0] == _COMMA:
                self._advance()
                args.append(self._parse_additive())

        if self._current[0] != _RPAREN:
            if self._current[0] == _EOF:
                raise self._unbalanced("unbalanced parentheses: missing ')'")
            raise self._unexpected()
        self._advance()

        if name == "abs":
            if len(args) != 1:
                raise CalcError("abs() takes exactly 1 argument")
            return self._call_function(abs, args)

        if name in ("min", "max"):
            if len(args) < 1:
                raise CalcError("{}() requires at least 1 argument".format(name))
            fn = min if name == "min" else max
            return self._call_function(fn, args)

        raise CalcError("unknown function: {!r}".format(name))

    @staticmethod
    def _call_function(fn, args):
        try:
            result = fn(*args)
        except (TypeError, ValueError, OverflowError) as exc:
            raise CalcError("invalid argument(s) to function: {}".format(exc))
        return result

    @staticmethod
    def _apply_unary(op, value):
        try:
            if op == "+":
                return +value
            return -value
        except (TypeError, ValueError, OverflowError) as exc:
            raise CalcError("invalid operand for unary '{}': {}".format(op, exc))

    @staticmethod
    def _apply_binary(op, left, right):
        try:
            if op == "+":
                result = left + right
            elif op == "-":
                result = left - right
            elif op == "*":
                result = left * right
            elif op == "/":
                result = left / right
            elif op == "//":
                result = left // right
            elif op == "%":
                result = left % right
            elif op == "**":
                result = left ** right
            else:  # Defensive: the parser should never produce another op.
                raise CalcError("unexpected operator: {!r}".format(op))
        except ZeroDivisionError:
            if op in ("/", "//"):
                raise CalcError("division by zero")
            if op == "%":
                raise CalcError("modulo by zero")
            raise CalcError("zero cannot be raised to a negative power")
        except (TypeError, ValueError, OverflowError) as exc:
            raise CalcError("invalid operands for '{}': {}".format(op, exc))

        if isinstance(result, complex):
            raise CalcError("result is not a real number")
        return result


def evaluate(expr: str, env: dict | None = None) -> int | float:
    """Evaluate *expr* using variables from *env*.

    Raises :class:`CalcError` for malformed expressions and the error cases
    described by the language specification.
    """
    if not isinstance(expr, str):
        raise CalcError("expression must be a string")
    if env is None:
        env = {}
    return _Parser(expr, env).parse()
